package android.view;import java.util.*;
public final class ViewTreeObserver {public interface OnPreDrawListener{boolean onPreDraw();}private final ArrayList<OnPreDrawListener> listeners=new ArrayList<OnPreDrawListener>();public boolean alive=true;public boolean isAlive(){return alive;}public void addOnPreDrawListener(OnPreDrawListener l){listeners.add(l);}public void removeOnPreDrawListener(OnPreDrawListener l){listeners.remove(l);}public int hostListenerCount(){return listeners.size();}public boolean hostDispatch(){boolean result=true;for(OnPreDrawListener l:new ArrayList<OnPreDrawListener>(listeners))result=l.onPreDraw()&&result;return result;}}
